var b=$input.first().json.body||$input.first().json;
var type=String(b.documentType||b.docType||'').toLowerCase().trim();
var allowed=['proof_of_funds','bank_statement','funding_letter','entity_document','assignment_document','insurance','id_verification','other'];
if(allowed.indexOf(type)<0) type='other';
return [{json:{...b,buyerId:String(b.buyerId||''),dealId:String(b.dealId||''),assignmentId:String(b.assignmentId||''),documentId:String(b.documentId||''),documentType:type,documentUrl:String(b.documentUrl||''),receivedAt:new Date().toISOString()}}];

var d=$input.first().json;
var identity=!!d.buyerId&&!!d.documentId;
var url=!!String(d.documentUrl||'');
var type=String(d.documentType||'other');
var supported=['proof_of_funds','bank_statement','funding_letter','entity_document','assignment_document','insurance','id_verification','other'].indexOf(type)>=0;
var integrity=d.documentIntegrityVerified!==false;
var current=d.documentCurrent!==false;
var readable=d.documentReadable!==false;
var authenticity=d.documentAuthenticityVerified===true||d.documentVerificationStatus==='verified';
var pofComplete=type!=='proof_of_funds'||(authenticity&&current&&readable);
var failed=!identity||!url||!supported||!integrity||!readable||!current||!pofComplete;
var status=failed?'rejected':authenticity?'verified':'pending_review';
var reasons=[]; if(!identity) reasons.push('missing_buyer_or_document_identity'); if(!url) reasons.push('missing_document_url'); if(!integrity) reasons.push('document_integrity_failed'); if(!readable) reasons.push('document_not_readable'); if(!current) reasons.push('document_not_current'); if(type==='proof_of_funds'&&!authenticity) reasons.push('proof_of_funds_authenticity_not_verified');
return [{json:{...d,documentVerificationStatus:status,documentVerificationFailed:failed,verificationReasons:reasons}}];

var d=$input.first().json;
var dealState=String(d.dealStatus||'').toLowerCase();
var protectedDeal=['closed','cancelled','disputed'].indexOf(dealState)>=0;
var buyerBlocked=d.buyerActive===false||d.buyerSuppressed===true||d.dnc===true;
var allowed=!d.documentVerificationFailed&&!protectedDeal&&!buyerBlocked;
var reason=allowed?null:protectedDeal?'deal_protected':buyerBlocked?'buyer_blocked':(d.verificationReasons||['document_verification_failed'])[0];
return [{json:{...d,documentVerificationAllowed:allowed,documentVerificationBlockedReason:reason}}];
